import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.next();
        int length = s.length();
        int index = 0;
        boolean first_at = true, first_dot = true;
        StringBuilder output = new StringBuilder();

        while (index < length) {
            if (index + 1 < length && s.charAt(index) == 'a' && s.charAt(index + 1) == 't' && first_at && index != 0) {
                output.append("@");
                index += 2;
                first_at = false;
                continue;
            }
            if (index + 2 < length && s.charAt(index) == 'd' && s.charAt(index + 1) == 'o' && s.charAt(index + 2) == 't' && index != 0 && index + 2 != length - 1) {
                output.append(".");
                index += 3;
                continue;
            } else {
                output.append(s.charAt(index));
                index++;
            }
        }
        System.out.println(output.toString());
        scanner.close();
    }
}
